async fn access_log_middleware(
    State(config): State<AccessLogConfig>,
    request: Request<axum::body::Body>,
    next: Next,
) -> Response {
    let log_level = config.access_log_level;
    let start = Instant::now();
    let method = request.method().clone();
    let path = request.uri().path().to_owned();
    let response = next.run(request).await;
    let latency = start.elapsed();
    let request_id = response
        .headers()
        .get(&REQUEST_ID_HEADER)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("-");
    let status = response.status();
    let body_size = response
        .headers()
        .get(axum::http::header::CONTENT_LENGTH)
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(0);
    if path.starts_with("/health/") {
        if log_level >= tracing::Level::DEBUG {
            tracing::debug!(
                http.method = %method,
                http.path = path,
                http.status_code = %status,
                http.response_bytes = body_size,
                latency_ms = latency.as_millis(),
                request_id = request_id,
                "access_log"
            );
        }
    } else if log_level >= tracing::Level::INFO {
        tracing::info!(
            http.method = %method,
            http.path = path,
            http.status_code = %status,
            http.response_bytes = body_size,
            latency_ms = latency.as_millis(),
            request_id = request_id,
            "access_log"
        );
    }
    response
}

pub(crate) async fn authenticated_session(
    State(manager): State<SessionManager>,
    mut request: Request<axum::body::Body>,
    next: Next,
) -> Result<Response, ApiError> {
    let session = manager
        .authenticate(session_cookie(
            request.headers(),
            manager.uses_secure_cookies(),
        ))
        .await
        .map_err(map_session_error)?;
    manager
        .enforce_csrf(request.method(), request.headers(), &session)
        .map_err(map_session_error)?;
    request.extensions_mut().insert(session);
    Ok(next.run(request).await)
}

async fn inspect_session(
    Extension(session): Extension<AuthenticatedSession>,
) -> Json<AuthenticatedSession> {
    Json(session)
}

async fn logout_current(
    State(state): State<ApplicationState>,
    Extension(session): Extension<AuthenticatedSession>,
) -> Result<impl IntoResponse, ApiError> {
    let manager = state
        .session_manager
        .ok_or_else(ApiError::service_unavailable)?;
    manager
        .logout_current(&session)
        .await
        .map_err(map_session_error)?;
    Ok(logout_response(manager.uses_secure_cookies()))
}

async fn logout_all(
    State(state): State<ApplicationState>,
    Extension(session): Extension<AuthenticatedSession>,
) -> Result<impl IntoResponse, ApiError> {
    let manager = state
        .session_manager
        .ok_or_else(ApiError::service_unavailable)?;
    manager
        .logout_all(&session)
        .await
        .map_err(map_session_error)?;
    Ok(logout_response(manager.uses_secure_cookies()))
}

fn logout_response(secure: bool) -> (StatusCode, HeaderMap) {
    let mut headers = HeaderMap::new();
    headers.insert(
        SET_COOKIE,
        HeaderValue::from_static(if secure {
            "__Host-commoncal_session=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Lax"
        } else {
            "commoncal_session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax"
        }),
    );
    (StatusCode::NO_CONTENT, headers)
}

